 const leaf=new Error('resource leaf'),original=new AggregateError([leaf],'application cleanup'),inspection=new Error('second indexed read'),sinkFailure=new Error('sink failure'),required=new Error('required fault');
 let memberReads=0;const members=new Proxy([leaf],{get(target,key,receiver){if(key==='0'&&++memberReads===2)throw inspection;return Reflect.get(target,key,receiver);}});original.errors=members;
 const events=[],faults=[],cleanup=[];
 const diagnostics={faultReporter:f=>faults.push(f),...(mode==='no-sink-required-fault'?{}:{sink:event=>{events.push(event);if(mode==='sink-fault'&&event.name===runtimeDiagnosticEvents.installationDisposeFailed)throw sinkFailure;}})};
 const host=createPluginHost({diagnostics});
 const installation=host.install(definePlugin({setup(context){
  if(mode==='no-sink-required-fault')context.diagnostics.reportFault(required,{name:'probe.required-fault'});
  context.own(()=>{cleanup.push('early');});context.own(()=>{cleanup.push('failure');throw original;});context.own(()=>{cleanup.push('late');});
 }}));
 await installation.whenActive();
 const promise=route==='host'?host.dispose():installation.dispose();assert.equal(route==='host'?host.dispose():installation.dispose(),promise);
 const outcome=await promise.then(()=>({ok:true}),error=>({ok:false,error}));assert.equal(outcome.ok,false);
 function contains(root,expected,seen=new Set()) {
  if(Object.is(root,expected))return true;
  if(root===original||root===null||typeof root!=='object'||seen.has(root))return false;
  seen.add(root);const descriptor=Object.getOwnPropertyDescriptor(root,'errors');
  if(!descriptor||!('value'in descriptor)||!Array.isArray(descriptor.value)||descriptor.value===members)return false;
  for(let index=0;index<descriptor.value.length;index++){const child=Object.getOwnPropertyDescriptor(descriptor.value,String(index));if(child&&'value'in child&&contains(child.value,expected,seen))return true;}
  return false;
 }
 assert.equal(contains(outcome.error,original),true);assert.deepEqual(cleanup,['late','failure','early']);assert.equal(installation.getSnapshot().status,'disposed');
 const repeated=await (route==='host'?host.dispose():installation.dispose()).then(()=>undefined,error=>error);assert.equal(repeated,outcome.error);
 if(mode==='no-sink-required-fault'){assert.equal(memberReads,0);assert.equal(contains(outcome.error,inspection),false);assert.equal(events.length,0);assert.equal(faults.length,1);assert.equal(faults[0].error,required);}
 else {assert.equal(memberReads,2);assert.equal(contains(outcome.error,inspection),true);const failures=events.filter(e=>e.name===runtimeDiagnosticEvents.installationDisposeFailed);assert.equal(failures.length,1);assert.equal(contains(outcome.error,failures[0].error),true);if(route==='installation')assert.equal(outcome.error,failures[0].error);if(mode==='sink-fault'){assert.equal(faults.length,1);assert.equal(faults[0].error,sinkFailure);assert.equal(contains(outcome.error,sinkFailure),false);}else assert.equal(faults.length,0);}
 if(route==='installation')await host.dispose();else await host.dispose().catch(error=>assert.equal(error,outcome.error));
 assert.equal(Object.isFrozen(members),false);
 observations.push({route,mode,memberReads,requiredFaults:faults.length,originalRetained:true,inspectionRetained:mode!=='no-sink-required-fault',cachedOutcome:true,passed:true});
}
