 Object.defineProperty(original,'errors',{get(){reads++;throw inspection;}});
 const events=[],faults=[];
 const renderer={updateDocument(){},updateSession(){},updateInteraction(){},subscribeInput(){return ()=>{};},hitTest(){return null;},capturePointer(){},releasePointer(){},focus(){},async dispose(){disposeCalls++;throw original;}};
 class Connection {materializeEdge(input){materializeCalls++;return{id:edgeId('unused'),type:'link',source:input.source,target:input.target,data:null};}}
 const host=createPluginHost({diagnostics:{faultReporter:f=>faults.push(f),...(withSink?{sink:e=>events.push(e)}:{})}});
 const composition=host.install(createBasicCanvasPlugin(()=>renderer,{interaction:{connection:new Connection()}}));
 await composition.whenActive();assert.equal(composition.getSnapshot().status,'active');assert.equal(materializeCalls,0);
 const promise=host.dispose();assert.equal(host.dispose(),promise);const outcome=await promise.then(()=>({ok:true}),error=>({ok:false,error}));assert.equal(outcome.ok,false);
 function contains(root,expected,seen=new Set()) {if(Object.is(root,expected))return true;if(root===original||root===null||typeof root!=='object'||seen.has(root))return false;seen.add(root);const d=Object.getOwnPropertyDescriptor(root,'errors');if(!d||!('value'in d)||!Array.isArray(d.value))return false;for(let i=0;i<d.value.length;i++){const c=Object.getOwnPropertyDescriptor(d.value,String(i));if(c&&'value'in c&&contains(c.value,expected,seen))return true;}return false;}
 assert.equal(contains(outcome.error,original),true);assert.equal(disposeCalls,1);assert.equal(materializeCalls,0);assert.equal(composition.getSnapshot().status,'disposed');assert.equal(faults.length,0);
 if(withSink){assert.ok(events.some(e=>e.level==='error'&&contains(e.error,original)));if(reads>0)assert.equal(contains(outcome.error,inspection),true);}
 else {assert.equal(reads,0);assert.equal(events.length,0);assert.equal(contains(outcome.error,inspection),false);}
 const repeated=await host.dispose().then(()=>undefined,error=>error);assert.equal(repeated,outcome.error);assert.equal(disposeCalls,1);
 observations.push({withSink,activeInheritedConnection:true,materializeCalls,disposeCalls,inspectionReads:reads,originalRetained:true,inspectionRetainedIfRead:reads===0||contains(outcome.error,inspection),cachedOutcome:true,passed:true,scope:'actual Basic+seven public Plugin children with explicit public Renderer provider; no native/browser claim'});
}
console.log(JSON.stringify({checks:observations.length,passed:observations.length,observations}));
